/* Zego Design System — bundled behaviour (generated by build-dist.py). */


/* ==== components/address-lookup/address-lookup.js ==== */
/*
 * ============================================================
 * ADDRESS LOOKUP — search, choose, edit
 * ============================================================
 * Drives the three stages described in address-lookup.css. Opt in with
 * data-address-lookup on the wrapper; the stages are marked with
 * data-stage="search|chosen|manual" and only one is ever shown.
 *
 * SEARCHING IS FAKED. There is no address service behind this, so a search
 * builds four plausible addresses from whatever postcode was typed — enough for
 * the flow to be exercised with any input, which is what a prototype needs. The
 * street and town come from data-sample-street / data-sample-town so the copy
 * stays in the markup. Swap `results()` for a fetch when there is a real service.
 *
 * FLOW
 *   type a postcode → search (button, Enter or the glyph) → results open
 *   pick a result                → CHOSEN, summary shows the address
 *   pick "Enter address manually" → MANUAL, empty fields
 *   Edit on the summary           → MANUAL, fields pre-filled from the address
 *   Save address                  → CHOSEN, summary shows what was typed
 *
 * The chosen address is written to a hidden input so everything that reads
 * `.input` values — form serialisation, the journey's required-field gate — sees
 * the address as one answered field rather than four, or none.
 *
 * Self-initialising via event delegation:
 *   <script src="address-lookup.js" defer></script>
 * ============================================================
 */

(function () {
  var POSTCODE = /^[A-Z]{1,2}\d[A-Z\d]?\s*\d[A-Z]{2}$/i;

  function stage(root, name) { return root.querySelector('[data-stage="' + name + '"]'); }
  function show(root, name) {
    ['search', 'chosen', 'manual'].forEach(function (s) {
      var el = stage(root, s);
      if (el) el.hidden = s !== name;
    });
    var results = root.querySelector('.address-lookup__results');
    if (results) results.hidden = true;
  }

  function field(root, name) { return root.querySelector('[data-address="' + name + '"]'); }

  /* The value everything else reads: the whole address on one line. The parts
     are kept alongside it so Edit can open the form already filled in, which is
     what the design shows — being sent back to four empty fields after choosing
     an address would be worse than not offering Edit at all. */
  function commit(root, parts) {
    root.dataset.chosen = JSON.stringify(parts);

    var store = field(root, 'value');
    if (!store) return;
    store.value = lines(parts).join(', ');
    store.dispatchEvent(new Event('input',  { bubbles: true }));
    store.dispatchEvent(new Event('change', { bubbles: true }));
  }

  /* How an address reads: street, then anything else, then town + postcode */
  function lines(parts) {
    return [
      parts.line1,
      parts.line2,
      [parts.city, parts.postcode].filter(Boolean).join(', ')
    ].filter(Boolean);
  }

  function chosen(root) {
    try { return JSON.parse(root.dataset.chosen || '{}'); } catch (e) { return {}; }
  }

  var FIELDS = { line1: 'line1', line2: 'line2', city: 'city', postcode: 'postcode-manual' };

  function fill(root, parts) {
    Object.keys(FIELDS).forEach(function (key) {
      var el = field(root, FIELDS[key]);
      if (el) el.value = parts[key] || '';
    });
  }

  function read(root) {
    var parts = {};
    Object.keys(FIELDS).forEach(function (key) {
      var el = field(root, FIELDS[key]);
      parts[key] = el ? el.value.trim() : '';
    });
    return parts;
  }

  function summarise(root, parts) {
    var box = root.querySelector('.address-lookup__lines');
    if (box) box.innerHTML = lines(parts).map(function (l, i) {
      return i ? '<br>' + l : l;
    }).join('');
  }


  /* --- faked search ----------------------------------------------------- */

  function results(root, postcode) {
    var street = root.dataset.sampleStreet || 'Elaine Street';
    var town   = root.dataset.sampleTown   || 'Liverpool';
    var tidy   = postcode.toUpperCase().replace(/\s+/g, ' ').trim();
    var out = [];
    for (var n = 1; n <= 4; n++) {
      out.push({ line1: n + ' ' + street, line2: town + ', ' + tidy });
    }
    return out;
  }

  var CHEVRON = '<svg viewBox="0 0 7 12" fill="none" aria-hidden="true"><path d="M1.98792 0.169026C1.75193 -0.0595573 1.37599 -0.0558328 1.14457 0.177381L0.174098 1.1554C-0.061348 1.39267 -0.0574932 1.7766 0.18267 2.0091L3.77064 5.48258C3.93167 5.63848 3.9332 5.89626 3.77401 6.05405L0.285904 9.51164C0.0495571 9.74592 0.049031 10.1278 0.284731 10.3627L1.26078 11.3356C1.49447 11.5685 1.8724 11.569 2.10674 11.3367L6.29663 7.18351C7.09241 6.39469 7.08497 5.10608 6.28013 4.32651L1.98792 0.169026Z" fill="currentColor"/></svg>';

  function search(root) {
    var input = field(root, 'postcode');
    var list  = root.querySelector('.address-lookup__results');
    if (!input || !list) return;

    var postcode = input.value.trim();
    if (!postcode) return;

    var rows = results(root, postcode).map(function (a) {
      return '<button class="dropdown-item address-lookup__result" type="button" role="option"'
           + ' data-line1="' + a.line1 + '" data-line2="' + a.line2 + '">'
           + '<span class="address-lookup__result-text">'
           +   '<span class="dropdown-item__label">' + a.line1 + '</span>'
           +   '<span class="address-lookup__result-sub">' + a.line2 + '</span>'
           + '</span></button>';
    });

    rows.push('<button class="dropdown-item address-lookup__manual-link" type="button"'
      + ' data-address-manual>'
      + '<span class="dropdown-item__label">' + (root.dataset.manualLabel || 'Enter address manually') + '</span>'
      + '<span class="address-lookup__chevron">' + CHEVRON + '</span></button>');

    list.innerHTML = rows.join('');
    list.hidden = false;
    input.setAttribute('aria-expanded', 'true');
  }


  /* --- wiring ----------------------------------------------------------- */

  document.addEventListener('click', function (event) {
    var root = event.target.closest && event.target.closest('[data-address-lookup]');

    /* a click anywhere else closes an open result list */
    if (!root) {
      document.querySelectorAll('[data-address-lookup] .address-lookup__results')
        .forEach(function (l) { l.hidden = true; });
      return;
    }

    if (event.target.closest('[data-address-search]')) { search(root); return; }

    var picked = event.target.closest('.address-lookup__result');
    if (picked) {
      /* the second line of a result is "Town, POSTCODE" */
      var tail  = (picked.getAttribute('data-line2') || '').split(',');
      var parts = {
        line1:    picked.getAttribute('data-line1') || '',
        line2:    '',
        city:     (tail[0] || '').trim(),
        postcode: (tail[1] || '').trim()
      };
      summarise(root, parts);
      commit(root, parts);
      show(root, 'chosen');
      return;
    }

    if (event.target.closest('[data-address-manual]')) {
      fill(root, {});                       /* nothing chosen yet — start empty */
      show(root, 'manual');
      var first = field(root, 'line1');
      if (first) first.focus();
      return;
    }

    if (event.target.closest('[data-address-edit]')) {
      fill(root, chosen(root));             /* open on what was chosen */
      show(root, 'manual');
      var line1 = field(root, 'line1');
      if (line1) line1.focus();
      return;
    }

    if (event.target.closest('[data-address-save]')) {
      var typed = read(root);
      summarise(root, typed);
      commit(root, typed);
      show(root, 'chosen');
      return;
    }
  });

  /* Enter in the postcode field searches rather than submitting the page */
  document.addEventListener('keydown', function (event) {
    var el = event.target;
    if (!el.matches || !el.matches('[data-address="postcode"]')) return;
    if (event.key !== 'Enter') return;
    event.preventDefault();
    var root = el.closest('[data-address-lookup]');
    if (root) search(root);
  });

  /* Typing a complete postcode is enough to offer results without pressing
     anything — the glyph is still there for anyone who expects to click it. */
  document.addEventListener('input', function (event) {
    var el = event.target;
    if (!el.matches || !el.matches('[data-address="postcode"]')) return;
    var root = el.closest('[data-address-lookup]');
    if (!root) return;
    if (POSTCODE.test(el.value.trim())) search(root);
    else {
      var list = root.querySelector('.address-lookup__results');
      if (list) list.hidden = true;
    }
  });
})();


/* ==== components/alert/alert.js ==== */
/*
 * ============================================================
 * ALERT — dismiss behaviour
 * ============================================================
 * Clicking .alert__close fades the parent .alert out and removes it.
 *
 * Self-initialising via event delegation — just include the script:
 *   <script src="alert.js"></script>
 * ============================================================
 */

(function () {
  document.addEventListener('click', function (event) {
    var closeBtn = event.target.closest('.alert__close');
    if (!closeBtn) return;

    var alert = closeBtn.closest('.alert');
    if (!alert) return;

    var remove = function () { if (alert.isConnected) alert.remove(); };

    // Graceful fade, then remove (with a timeout fallback if the
    // transition doesn't fire, e.g. reduced-motion / display quirks).
    alert.style.transition = 'opacity 150ms ease';
    alert.style.opacity = '0';
    alert.addEventListener('transitionend', remove, { once: true });
    setTimeout(remove, 250);
  });
})();


/* ==== components/bottom-nav/bottom-nav.js ==== */
/*
 * ============================================================
 * BOTTOM NAV — interactivity
 * ============================================================
 * Single-select: clicking a tab makes it the active one (filled icon +
 * .bottom-nav__item--active + aria-current) and clears the others.
 *
 * Applies to every .bottom-nav on the page. Add data-static to a bar to
 * opt it out (e.g. a reference row that should show a fixed state).
 *
 * Each item must contain both glyphs so the icon can swap without JS
 * touching the markup:
 *   <span class="bottom-nav__icon">
 *     <span class="bottom-nav__glyph bottom-nav__glyph--line"><svg>…</svg></span>
 *     <span class="bottom-nav__glyph bottom-nav__glyph--fill"><svg>…</svg></span>
 *   </span>
 * ============================================================
 */
(function () {
  function activate(nav, item) {
    nav.querySelectorAll('.bottom-nav__item').forEach(function (it) {
      var on = it === item;
      it.classList.toggle('bottom-nav__item--active', on);
      if (on) it.setAttribute('aria-current', 'page');
      else it.removeAttribute('aria-current');
    });
  }

  function init(nav) {
    if (nav.dataset.bottomNavReady) return;      // guard against double-init
    nav.dataset.bottomNavReady = '1';
    nav.addEventListener('click', function (e) {
      var item = e.target.closest('.bottom-nav__item');
      if (!item || !nav.contains(item)) return;
      e.preventDefault();
      activate(nav, item);
    });
  }

  function boot() {
    document.querySelectorAll('.bottom-nav:not([data-static])').forEach(init);
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', boot);
  } else {
    boot();
  }
})();


/* ==== components/comparison-tile/comparison-tile.js ==== */
/*
 * ============================================================
 * COMPARISON TILE — selection behaviour
 * ============================================================
 * Keeps the .comparison-tile--active class in sync with the selected radio
 * across a group (tiles sharing the same radio `name`). Selecting one tile
 * activates it and deactivates the previously-active one.
 *
 * (The frame colour also updates on its own via :has(.radio__input:checked);
 * this handler additionally clears any stale --active force class so the
 * previously-active tile fully resets.)
 *
 * Self-initialising via event delegation — just include the script:
 *   <script src="comparison-tile.js"></script>
 * ============================================================
 */

(function () {
  document.addEventListener('change', function (event) {
    var input = event.target;
    if (!(input instanceof HTMLInputElement) || input.type !== 'radio') return;
    if (!input.closest('.comparison-tile') || !input.name) return;

    var group = document.querySelectorAll(
      '.comparison-tile .radio__input[name="' + (window.CSS && CSS.escape ? CSS.escape(input.name) : input.name) + '"]'
    );
    if (group.length < 2) return; // only manage real multi-option groups

    group.forEach(function (radio) {
      var tile = radio.closest('.comparison-tile');
      if (tile) tile.classList.toggle('comparison-tile--active', radio.checked);
    });
  });
})();


/* ==== components/conditional-selector/conditional-selector.js ==== */
/*
 * ============================================================
 * CONDITIONAL SELECTOR — reveal the follow-up
 * ============================================================
 * Shows .conditional-selector__panel while the answer marked data-reveals is
 * the one selected, and hides it again otherwise. Marking the triggering radio
 * rather than naming a value in a data attribute keeps the two from drifting
 * apart when the option copy changes.
 *
 * More than one answer can carry data-reveals — the panel opens for any of
 * them, which covers "tell us more" following several options.
 *
 * Closing the panel **clears the follow-up**, so coming back to it means
 * answering again. A hidden answer that quietly persists is the wrong default:
 * it can still be read at submit, and on a screen that routes off an answer it
 * can send someone somewhere they didn't choose. Any error the follow-up was
 * showing goes too, since a hidden field complaining about itself is nonsense.
 *
 * Self-initialising via event delegation, and it syncs markup that starts out
 * answered — just include the script:
 *   <script src="conditional-selector.js" defer></script>
 * ============================================================
 */

(function () {
  function sync(root) {
    var panel = root.querySelector('.conditional-selector__panel');
    if (!panel) return;

    var triggers = root.querySelectorAll('[data-reveals]');
    var open = Array.prototype.some.call(triggers, function (el) { return el.checked; });

    if (panel.hidden === !open) return;            /* already in the right state */
    panel.hidden = !open;

    if (!open) {
      /* Clear the answers, so reopening asks again rather than remembering */
      panel.querySelectorAll('input, select, textarea').forEach(function (el) {
        if (el.type === 'radio' || el.type === 'checkbox') el.checked = false;
        else el.value = '';
      });

      /* Drop any error the follow-up was showing — it can't be answered now */
      panel.querySelectorAll('[data-journey-invalid]').forEach(function (el) {
        el.removeAttribute('data-journey-invalid');
      });
      panel.querySelectorAll('.journey-error').forEach(function (msg) { msg.remove(); });
      panel.querySelectorAll('.input-field--error').forEach(function (field) {
        field.classList.remove('input-field--error');
      });
      panel.querySelectorAll('[aria-invalid]').forEach(function (el) {
        el.removeAttribute('aria-invalid');
        el.removeAttribute('aria-describedby');
      });
    }
  }

  document.addEventListener('change', function (event) {
    var root = event.target.closest && event.target.closest('.conditional-selector');
    if (root) sync(root);
  });

  document.addEventListener('DOMContentLoaded', function () {
    document.querySelectorAll('.conditional-selector').forEach(sync);
  });
})();


/* ==== components/date-picker/date-picker.js ==== */
/*
 * ============================================================
 * DATE PICKER — render + navigation + selection
 * ============================================================
 * Renders each .date-picker from its data attributes and wires the prev/next
 * month buttons and day selection.
 *
 *   data-year, data-month (0–11) — the visible month
 *   data-selected  "YYYY-M-D"    — the chosen day (M is 0–11)
 *   data-today     "YYYY-M-D"    — the day drawn with the "today" outline
 *   data-min, data-max "YYYY-M-D" — optional bounds. Days outside them render
 *                                   disabled, and the month arrows stop rather
 *                                   than walking into a month with nothing in it.
 *                                   For a question that only accepts a window —
 *                                   "cover must start within 30 days".
 *
 * Weeks start on Monday. Selecting a day updates data-selected and re-renders.
 * Self-init via event delegation:  <script src="date-picker.js" defer></script>
 * ============================================================
 */
(function () {
  var MONTHS = ['January', 'February', 'March', 'April', 'May', 'June',
    'July', 'August', 'September', 'October', 'November', 'December'];
  var WEEKDAYS = ['M', 'T', 'W', 'T', 'F', 'S', 'S'];

  function key(y, m, d) { return y + '-' + m + '-' + d; }

  /* "YYYY-M-D" as a number that sorts, so bounds can be compared without Date */
  function ord(k) {
    if (!k) return null;
    var p = k.split('-');
    return (+p[0]) * 10000 + (+p[1]) * 100 + (+p[2]);
  }

  function bounds(dp) {
    return { min: ord(dp.getAttribute('data-min')), max: ord(dp.getAttribute('data-max')) };
  }

  function outside(b, y, m, d) {
    var v = ord(key(y, m, d));
    return (b.min !== null && v < b.min) || (b.max !== null && v > b.max);
  }

  function render(dp) {
    var year = parseInt(dp.getAttribute('data-year'), 10);
    var month = parseInt(dp.getAttribute('data-month'), 10);
    var selected = dp.getAttribute('data-selected') || '';
    var today = dp.getAttribute('data-today') || '';

    var title = dp.querySelector('.date-picker__title');
    if (title) title.textContent = MONTHS[month] + ' ' + year;

    var grid = dp.querySelector('.date-picker__grid');
    if (!grid) return;

    var firstDow = (new Date(year, month, 1).getDay() + 6) % 7;   // Mon = 0
    var daysInMonth = new Date(year, month + 1, 0).getDate();

    var cells = '';
    for (var i = 0; i < firstDow; i++) {
      cells += '<span class="date-picker__day date-picker__day--empty" aria-hidden="true"></span>';
    }
    var b = bounds(dp);
    for (var d = 1; d <= daysInMonth; d++) {
      var k = key(year, month, d);
      var cls = 'date-picker__day';
      if (k === selected) cls += ' date-picker__day--selected';
      if (k === today) cls += ' date-picker__day--today';
      var pressed = k === selected ? ' aria-pressed="true"' : '';
      /* Out of bounds days are shown and disabled rather than hidden: the shape
         of the month stays readable, and it is clear the day exists but can't be
         chosen. */
      var off = outside(b, year, month, d) ? ' disabled' : '';
      cells += '<button type="button" class="' + cls + '" data-day="' + d + '"' + pressed + off + '>' + d + '</button>';
    }
    grid.innerHTML = cells;

    /* Stop the arrows at the edge of the window — a month with every day greyed
       out is a dead end you have to find your own way back from. */
    var prev = dp.querySelector('.date-picker__prev');
    var next = dp.querySelector('.date-picker__next');
    if (prev) prev.disabled = b.min !== null && ord(key(year, month, 1)) <= b.min;
    if (next) next.disabled = b.max !== null && ord(key(year, month, daysInMonth)) >= b.max;
  }

  function shiftMonth(dp, delta) {
    var year = parseInt(dp.getAttribute('data-year'), 10);
    var month = parseInt(dp.getAttribute('data-month'), 10) + delta;
    if (month < 0) { month = 11; year--; }
    else if (month > 11) { month = 0; year++; }
    dp.setAttribute('data-year', year);
    dp.setAttribute('data-month', month);
    render(dp);
  }

  document.addEventListener('click', function (event) {
    var prev = event.target.closest('.date-picker__prev');
    if (prev) { shiftMonth(prev.closest('.date-picker'), -1); return; }

    var next = event.target.closest('.date-picker__next');
    if (next) { shiftMonth(next.closest('.date-picker'), 1); return; }

    var day = event.target.closest('.date-picker__day[data-day]');
    if (day) {
      var dp = day.closest('.date-picker');
      dp.setAttribute('data-selected', key(
        parseInt(dp.getAttribute('data-year'), 10),
        parseInt(dp.getAttribute('data-month'), 10),
        parseInt(day.getAttribute('data-day'), 10)
      ));
      render(dp);
      return;
    }
  });

  /* Re-render when the data attributes change, so a picker can be DRIVEN: set
     data-year and data-month from script and the calendar follows. Without this
     a consumer that decides the month at runtime — "start from today" — renders
     once against whatever the markup happened to say and then never again.

     watch() skips the render it caused itself, or setting data-selected inside
     render would loop. */
  var rendering = false;

  function watch(dp) {
    if (dp._dpWatched) return;
    dp._dpWatched = true;
    new MutationObserver(function () {
      if (rendering) return;
      rendering = true;
      render(dp);
      rendering = false;
    }).observe(dp, { attributes: true,
      attributeFilter: ['data-year', 'data-month', 'data-selected', 'data-today',
                        'data-min', 'data-max'] });
  }

  function initAll() {
    document.querySelectorAll('.date-picker').forEach(function (dp) {
      render(dp);
      watch(dp);
    });
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initAll);
  } else {
    initAll();
  }
})();


/* ==== components/detail-card/detail-card.js ==== */
/*
 * ============================================================
 * DETAIL CARD — Incident type select
 * ============================================================
 * Clicking the "Incident type" field (a DS Input styled as a trigger) opens
 * the Dropdown List component 4px below it. Choosing a Dropdown Item fills the
 * field and closes the menu. Click-outside and Escape close it too.
 *
 * Self-initialising via event delegation — just include the script:
 *   <script src="detail-card.js" defer></script>
 * ============================================================
 */
(function () {
  function closeAll(except) {
    document.querySelectorAll('.detail-card__select--open').forEach(function (sel) {
      if (sel === except) return;
      sel.classList.remove('detail-card__select--open');
      var trigger = sel.querySelector('.detail-card__select-trigger');
      if (trigger) trigger.setAttribute('aria-expanded', 'false');
    });
  }

  function setView(el, view) {
    var card = el.closest('.detail-card');
    if (card) card.setAttribute('data-view', view);
    closeAll(null);
  }

  document.addEventListener('click', function (event) {
    // Mode switching: Save / Cancel → view, pencil → edit
    var save = event.target.closest('[data-dc-save]');
    if (save) { setView(save, 'view'); return; }
    var cancel = event.target.closest('[data-dc-cancel]');
    if (cancel) { setView(cancel, 'view'); return; }
    var edit = event.target.closest('[data-dc-edit]');
    if (edit) { setView(edit, 'edit'); return; }

    // Pick an option
    var item = event.target.closest('.detail-card__select-menu .dropdown-item');
    if (item) {
      var selFromItem = item.closest('.detail-card__select');
      var input = selFromItem.querySelector('.input');
      var label = item.querySelector('.dropdown-item__label');
      if (input) input.value = label ? label.textContent.trim() : item.textContent.trim();
      closeAll(null);
      return;
    }

    // Toggle the menu
    var trigger = event.target.closest('.detail-card__select-trigger');
    if (trigger) {
      var sel = trigger.closest('.detail-card__select');
      var isOpen = sel.classList.contains('detail-card__select--open');
      closeAll(sel);
      sel.classList.toggle('detail-card__select--open', !isOpen);
      trigger.setAttribute('aria-expanded', String(!isOpen));
      return;
    }

    // Click outside
    closeAll(null);
  });

  document.addEventListener('keydown', function (event) {
    if (event.key === 'Escape') closeAll(null);
  });
})();


/* ==== components/discount-code/discount-code.js ==== */
/*
 * ============================================================
 * DISCOUNT CODE — apply / error / remove behaviour
 * ============================================================
 * Each .discount-code holds a form and a hidden applied banner, switched via a
 * data-state attribute ("default" | "error" | "applied").
 *
 *   - Apply: if the entered code matches the valid code (data-code, default
 *     "ZEGO22", case-insensitive) → applied; otherwise → error.
 *   - Remove: clears the field and returns to default.
 *   - Editing the field after an error clears the error.
 *
 * A .discount-code--collapsible also opens and closes from its __toggle row,
 * tracked on data-open so the CSS can hide the form and turn the chevron.
 *
 * Pair with input.js so the clear (×) button empties the field. Self-init via
 * event delegation:  <script src="discount-code.js" defer></script>
 * ============================================================
 */
(function () {
  function setState(dc, state) {
    dc.setAttribute('data-state', state);
    var field = dc.querySelector('.input-field');
    if (field) field.classList.toggle('input-field--error', state === 'error');

    /* A collapsible one loses its collapse while a code is applied — the CSS hides
       the toggle, and this keeps data-open honest so nothing is left half-shut
       underneath it. Removing the code leaves it open with the field ready for
       another try, and the toggle comes back with it. */
    if (dc.classList.contains('discount-code--collapsible')) {
      dc.setAttribute('data-open', 'true');
      var t = dc.querySelector('.discount-code__toggle');
      if (t) t.setAttribute('aria-expanded', 'true');
    }
  }

  document.addEventListener('click', function (event) {
    /* Open / close a collapsible one. aria-expanded is set alongside data-open so
       the row announces its state rather than only looking like it has one. */
    var toggle = event.target.closest('.discount-code__toggle');
    if (toggle) {
      var host = toggle.closest('.discount-code');
      /* Nothing to fold while a code is applied; the toggle is hidden then, but a
         keyboard or a script could still reach it. */
      if (host && host.getAttribute('data-state') !== 'applied') {
        var open = host.getAttribute('data-open') !== 'true';
        host.setAttribute('data-open', open ? 'true' : 'false');
        toggle.setAttribute('aria-expanded', open ? 'true' : 'false');
        if (open) {
          var f = host.querySelector('.input');
          if (f) f.focus();
        }
      }
      return;
    }

    var apply = event.target.closest('.discount-code__apply');
    if (apply) {
      var dc = apply.closest('.discount-code');
      if (!dc) return;
      var input = dc.querySelector('.input');
      var value = (input && input.value || '').trim();
      if (!value) { if (input) input.focus(); return; }
      var valid = (dc.getAttribute('data-code') || 'ZEGO22').toUpperCase();
      setState(dc, value.toUpperCase() === valid ? 'applied' : 'error');
      return;
    }

    var remove = event.target.closest('.discount-code__remove');
    if (remove) {
      var card = remove.closest('.discount-code');
      if (!card) return;
      var field = card.querySelector('.input');
      if (field) field.value = '';
      setState(card, 'default');
      return;
    }
  });

  // Editing after an error clears the error (also catches input.js clears)
  document.addEventListener('input', function (event) {
    var input = event.target.closest('.discount-code .input');
    if (!input) return;
    var dc = input.closest('.discount-code');
    if (dc && dc.getAttribute('data-state') === 'error') setState(dc, 'default');
  });
})();


/* ==== components/extra-cover/extra-cover.js ==== */
/*
 * Extra Cover — add / remove toggle
 * Clicking .extra-cover__add toggles the card's added state: it reveals the
 * "Added" badge, flips the button from primary "Add" to secondary "Added"
 * (with a tick) and back.
 */
(function () {
  'use strict';

  function setState(card, added) {
    card.classList.toggle('extra-cover--added', added);
    var btn = card.querySelector('.extra-cover__add');
    if (!btn) return;
    btn.classList.toggle('btn--primary', !added);
    btn.classList.toggle('btn--secondary', added);
    btn.setAttribute('aria-pressed', added ? 'true' : 'false');
    var label = btn.querySelector('.extra-cover__add-label');
    if (label) label.textContent = added ? 'Remove' : 'Add';
  }

  document.addEventListener('click', function (e) {
    var btn = e.target.closest('.extra-cover__add');
    if (!btn) return;
    var card = btn.closest('.extra-cover');
    if (card) setState(card, !card.classList.contains('extra-cover--added'));
  });
})();


/* ==== components/global-alert/global-alert.js ==== */
/*
 * ============================================================
 * GLOBAL ALERT — raising, the cap, and the Success timer
 * ============================================================
 * Exposes one object:
 *
 *   GlobalAlert.show({ state, message, title, dismissible, timeout })  → element
 *   GlobalAlert.dismiss(element)
 *   GlobalAlert.clear()
 *   GlobalAlert.showing()                                             → array
 *
 *   state        'error' | 'warning' | 'success'   (default 'error')
 *   message      the sentence. Set as TEXT, never HTML — a message can carry a
 *                value someone typed, and that must not become markup.
 *   title        optional bold line above it
 *   dismissible  show the close (default true)
 *   timeout      ms before it retires itself. Defaults below.
 *
 * WHAT THIS FILE OWNS, and what it doesn't: the close button is Alert's own
 * behaviour (alert.js) and is deliberately not reimplemented here — load both.
 *
 * THE CAP IS TWO. A third message drops the OLDEST, because the newest is the one
 * that just happened and the stack has to stay readable. Two is a stack; a dozen
 * is a wall, and a wall gets dismissed unread.
 *
 * SUCCESS RETIRES ITSELF, ERROR AND WARNING PERSIST. A confirmation has been read
 * by the time it's understood, so leaving it there makes the reader tidy up after
 * good news. A fault has to be acted on, and a message that vanishes mid-read
 * takes the instruction with it. Warning sits with Error rather than with Success:
 * it is also something to act on. Override per call with `timeout`.
 * ============================================================
 */

(function () {
  var STATES = {
    error:   'alert--negative',
    warning: 'alert--warning',
    success: 'alert--positive'
  };

  /* 0 means never — see the note above */
  var TIMEOUTS = { error: 0, warning: 0, success: 5000 };

  var CAP = 2;

  /* icons/warning.svg — Error and Warning */
  var WARNING = '<svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M11 12.5C11 12.7761 11.2239 13 11.5 13H12.5C12.7761 13 13 12.7761 13 12.5L13 7.5C13 7.22386 12.7761 7 12.5 7L11.5 7C11.2239 7 11 7.22386 11 7.5L11 12.5Z" fill="currentColor"/><path d="M12 17C12.6904 17 13.25 16.4404 13.25 15.75C13.25 15.0596 12.6904 14.5 12 14.5C11.3096 14.5 10.75 15.0596 10.75 15.75C10.75 16.4404 11.3096 17 12 17Z" fill="currentColor"/><path fill-rule="evenodd" clip-rule="evenodd" d="M12 1C5.92487 1 1 5.92487 1 12C1 18.0751 5.92487 23 12 23C18.0751 23 23 18.0751 23 12C23 5.92487 18.0751 1 12 1ZM3 12C3 7.02944 7.02944 3 12 3C16.9706 3 21 7.02944 21 12C21 16.9706 16.9706 21 12 21C7.02944 21 3 16.9706 3 12Z" fill="currentColor"/></svg>';

  /* icons/tick.svg — Success. Outline, not the filled disc: inside a coloured
     alert the disc would be a second surface competing with the panel. */
  var TICK = '<svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path fill-rule="evenodd" clip-rule="evenodd" d="M12 1C5.92487 1 1 5.92487 1 12C1 18.0751 5.92487 23 12 23C18.0751 23 23 18.0751 23 12C23 5.92487 18.0751 1 12 1ZM3 12C3 7.02944 7.02944 3 12 3C16.9706 3 21 7.02944 21 12C21 16.9706 16.9706 21 12 21C7.02944 21 3 16.9706 3 12Z" fill="currentColor"/><path fill-rule="evenodd" clip-rule="evenodd" d="M10.4866 14.5576L15.9072 9.13697C16.1025 8.94171 16.4191 8.94171 16.6143 9.13697L17.3214 9.84408C17.5167 10.0393 17.5167 10.3559 17.3214 10.5512L10.8513 17.0213C10.656 17.2166 10.3394 17.2166 10.1442 17.0213L6.60355 13.4807C6.40829 13.2854 6.40829 12.9689 6.60355 12.7736L7.29953 12.0776C7.4948 11.8824 7.81138 11.8824 8.00664 12.0776L10.4866 14.5576Z" fill="currentColor"/></svg>';

  /* icons/close.svg */
  var CLOSE = '<svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><circle cx="12" cy="12" r="11" fill="currentColor" fill-opacity="0.3"/><path d="M14.7332 16.3392C14.9277 16.5389 15.2479 16.541 15.445 16.3439L16.1521 15.6369C16.3455 15.4435 16.3476 15.1305 16.1567 14.9345L13.3132 12.0141L16.2433 9.16117C16.443 8.96671 16.4452 8.64648 16.248 8.44937L15.541 7.74233C15.3476 7.54891 15.0346 7.54682 14.8386 7.73764L11.9181 10.5812L9.06528 7.6512C8.87082 7.45148 8.55059 7.44934 8.35349 7.64645L7.64644 8.35349C7.45302 8.54691 7.45093 8.85986 7.64175 9.05585L10.4853 11.9763L7.55531 14.8291C7.35559 15.0236 7.35345 15.3438 7.55056 15.5409L8.2576 16.2479C8.45103 16.4414 8.76397 16.4434 8.95996 16.2526L11.8804 13.4092L14.7332 16.3392Z" fill="currentColor"/></svg>';

  /* The stack, made on first use. Mounted on <body> so no ancestor with
     container-type / contain / a transform can capture the fixed positioning —
     that would pin it to a card instead of the viewport. */
  function stack() {
    var el = document.querySelector('[data-global-alert]');
    if (el) return el;
    el = document.createElement('div');
    el.className = 'global-alert';
    el.setAttribute('data-global-alert', '');
    /* polite, not assertive: it interrupts nothing, and an assertive region
       talks over whatever the reader is in the middle of */
    el.setAttribute('aria-live', 'polite');
    document.body.appendChild(el);
    return el;
  }

  function remove(el) {
    if (el._gaTimer) clearTimeout(el._gaTimer);
    if (el.isConnected) el.remove();
  }

  /* Fade, then remove — with a timeout fallback, since transitionend never fires
     under reduced-motion or on a hidden element */
  function retire(el) {
    if (el.dataset.leaving !== undefined) return;      /* already on its way out */
    el.dataset.leaving = '';
    el.addEventListener('transitionend', function () { remove(el); }, { once: true });
    setTimeout(function () { remove(el); }, 250);
  }

  function show(options) {
    var o     = options || {};
    var state = STATES[o.state] ? o.state : 'error';
    var host  = stack();

    var alert = document.createElement('div');
    alert.className = 'alert alert--bordered ' + STATES[state];
    /* role on the message, not the region: each one announces itself as it
       arrives, which is what a reader needs when two are on screen */
    alert.setAttribute('role', state === 'success' ? 'status' : 'alert');

    var icon = document.createElement('span');
    icon.className = 'alert__icon';
    icon.innerHTML = state === 'success' ? TICK : WARNING;
    alert.appendChild(icon);

    var content = document.createElement('div');
    content.className = 'alert__content';
    if (o.title) {
      var title = document.createElement('p');
      title.className = 'alert__title';
      title.textContent = o.title;                     /* text, never HTML */
      content.appendChild(title);
    }
    var body = document.createElement('p');
    body.className = 'alert__description';
    body.textContent = o.message || '';                /* text, never HTML */
    content.appendChild(body);
    alert.appendChild(content);

    if (o.dismissible !== false) {
      var close = document.createElement('button');
      close.className = 'alert__close';
      close.type = 'button';
      close.setAttribute('aria-label', 'Dismiss');
      close.innerHTML = CLOSE;
      alert.appendChild(close);                        /* alert.js does the rest */
    }

    host.appendChild(alert);

    /* Cap at two, oldest first — the newest is the one that just happened */
    while (host.children.length > CAP) remove(host.firstElementChild);

    var ms = o.timeout === undefined ? TIMEOUTS[state] : o.timeout;
    if (ms > 0) alert._gaTimer = setTimeout(function () { retire(alert); }, ms);

    return alert;
  }

  function showing() {
    var host = document.querySelector('[data-global-alert]');
    return host ? Array.prototype.slice.call(host.children) : [];
  }

  window.GlobalAlert = {
    show:    show,
    dismiss: function (el) { if (el) retire(el); },
    clear:   function () { showing().forEach(remove); },
    showing: showing
  };
})();


/* ==== components/input/input.js ==== */
/*
 * ============================================================
 * TEXT INPUT — clear button + segmented date entry
 * ============================================================
 * Wires up the clear (×) button shown in the focused / error states.
 * Clicking .input__clear empties the field's .input, re-focuses it and
 * fires an `input` event so any listeners (validation, etc.) update.
 *
 * Also drives the segmented MM / YYYY field — see the DATE ENTRY section below.
 *
 * Self-initialising via event delegation — just include the script:
 *   <script src="input.js"></script>
 * ============================================================
 */

(function () {
  // Keep focus on the field while the clear button is pressed. Without this,
  // the mousedown blurs the input, and clear buttons that are only revealed on
  // :focus-within (e.g. Search) get display:none before the click fires — so
  // the click is lost and the field never clears.
  document.addEventListener('mousedown', function (event) {
    if (event.target.closest('.input__clear')) event.preventDefault();
  });

  document.addEventListener('click', function (event) {
    var clearBtn = event.target.closest('.input__clear');
    if (!clearBtn) return;

    var field = clearBtn.closest('.input-field');
    var input = field && field.querySelector('.input');
    if (!input || input.disabled) return;

    input.value = '';
    input.dispatchEvent(new Event('input', { bubbles: true }));
    input.focus();
  });
})();


/*
 * ============================================================
 * SELECT — a field that opens a Dropdown List
 * ============================================================
 * Markup and the reasoning behind the readonly input are in the SELECT section
 * of input.css. Opt in with data-select on the group:
 *
 *   <div class="input-group input-select" data-select>
 *     <span class="input-label input-label--title" id="owner-label">…</span>
 *     <div class="input-field">
 *       <input class="input input-select__value" type="text" readonly placeholder="Select"
 *              role="combobox" aria-expanded="false" aria-controls="owner-list"
 *              aria-labelledby="owner-label">
 *       <span class="input-select__chevron">…UI / Chevron Small…</span>
 *     </div>
 *     <div class="dropdown-list input-select__list" id="owner-list" role="listbox" hidden>
 *       <button class="dropdown-item" type="button" role="option">
 *         <span class="dropdown-item__label">Option</span>
 *       </button>
 *     </div>
 *   </div>
 *
 * Picking a row writes its label into the field and fires input + change, so
 * listeners see it as an ordinary field edit. Clicking away or pressing Escape
 * closes it; Escape and a click on the field return focus to the field, since
 * losing your place after closing a menu is disorienting. Down/Up open the list
 * and step through the rows, which are real buttons, so Tab works too.
 * ============================================================
 */

(function () {
  function parts(root) {
    return {
      value: root.querySelector('.input-select__value'),
      list:  root.querySelector('.input-select__list')
    };
  }

  function open(root, yes) {
    var p = parts(root);
    if (!p.value || !p.list) return;
    root.setAttribute('data-open', yes ? 'true' : 'false');
    p.list.hidden = !yes;
    p.value.setAttribute('aria-expanded', yes ? 'true' : 'false');
  }

  function isOpen(root) { return root.getAttribute('data-open') === 'true'; }

  function closeAll(except) {
    document.querySelectorAll('[data-select][data-open="true"]').forEach(function (root) {
      if (root !== except) open(root, false);
    });
  }

  function rows(root) {
    return Array.prototype.slice.call(root.querySelectorAll('.input-select__list .dropdown-item'));
  }

  function choose(root, item) {
    var p = parts(root);
    var label = item.querySelector('.dropdown-item__label') || item;

    p.value.value = label.textContent.trim();
    rows(root).forEach(function (r) {
      r.setAttribute('aria-selected', String(r === item));
      r.hidden = false;              /* drop the filter — reopening shows them all */
    });

    open(root, false);
    p.value.focus();
    /* both, so validation listening for either kind of edit picks it up */
    p.value.dispatchEvent(new Event('input',  { bubbles: true }));
    p.value.dispatchEvent(new Event('change', { bubbles: true }));
  }

  /* --- FILTERING — data-select-filter ------------------------------------
     Turns the Select into a combo box: the field is typeable, and what is typed
     narrows the list instead of being the value. The value is still only ever
     chosen from the list, so nothing unrecognised can be submitted.

     Matching is on the row's whole label, so "SP30" and "speed" both find the
     same row — people search by the code they have OR the words they remember.
     ------------------------------------------------------------------------ */
  document.addEventListener('input', function (event) {
    var root = event.target.closest && event.target.closest('[data-select][data-select-filter]');
    if (!root) return;
    var p = parts(root);
    if (event.target !== p.value) return;

    var needle = p.value.value.trim().toLowerCase();
    var all = rows(root);

    /* The field now holds a whole row's label rather than a search term, so this
       is a CHOSEN value, not typing — choose() dispatches input so the gate and
       any other listener see the edit, and without this that echo would filter
       the list down to the one row just picked. Show everything and stand down. */
    var chosen = needle && all.some(function (r) { return r.textContent.trim().toLowerCase() === needle; });
    if (chosen) {
      all.forEach(function (r) { r.hidden = false; });
      return;
    }

    var shown = 0;
    all.forEach(function (r) {
      var hit = !needle || r.textContent.toLowerCase().indexOf(needle) !== -1;
      r.hidden = !hit;
      if (hit) shown++;
    });
    /* Nothing to choose from is worse than no menu at all */
    open(root, shown > 0);
  });

  document.addEventListener('click', function (event) {
    var root = event.target.closest && event.target.closest('[data-select]');
    if (!root) { closeAll(null); return; }     /* a click anywhere else closes */

    closeAll(root);

    var item = event.target.closest('.input-select__list .dropdown-item');
    if (item) { choose(root, item); return; }

    if (event.target.closest('.input-field')) {
      open(root, !isOpen(root));
      parts(root).value.focus();
    }
  });

  document.addEventListener('keydown', function (event) {
    var root = event.target.closest && event.target.closest('[data-select]');
    if (!root) return;
    var p = parts(root);
    var all = rows(root);

    if (event.key === 'Escape' && isOpen(root)) {
      open(root, false);
      p.value.focus();
      event.preventDefault();
      return;
    }

    if (event.target === p.value) {
      /* On a FILTERABLE select the field is a text box first: Space and Enter are
         typing and submitting, not "open the menu". Only the arrow moves focus
         into the list, and the list opens as you type (see the input handler). */
      var filtering = root.hasAttribute('data-select-filter');
      var opens = filtering ? ['ArrowDown'] : ['ArrowDown', 'Enter', ' '];
      if (opens.indexOf(event.key) !== -1) {
        if (!isOpen(root)) open(root, true);
        if (all.length) all[0].focus();
        event.preventDefault();          /* Space would scroll the page */
      }
      return;
    }

    var at = all.indexOf(event.target);
    if (at === -1) return;
    if (event.key === 'ArrowDown' && all[at + 1]) { all[at + 1].focus(); event.preventDefault(); }
    if (event.key === 'ArrowUp') {
      if (all[at - 1]) all[at - 1].focus();
      else p.value.focus();
      event.preventDefault();
    }
  });
})();


/*
 * ============================================================
 * COUNTER — data-counter
 * ============================================================
 * Keeps an .input-counter in step with what's typed:
 *
 *   <input class="input" maxlength="16" data-counter="licence-count">
 *   <p class="input-counter" id="licence-count">0 of 16</p>
 *
 * The total comes from maxlength, so there is one place to change it. Counts
 * characters as typed — no trimming — because that is what the field will hold.
 * ============================================================
 */

(function () {
  function sync(el) {
    var out = document.getElementById(el.dataset.counter);
    if (!out) return;
    var max = el.getAttribute('maxlength');
    out.textContent = el.value.length + (max ? ' of ' + max : '');
  }

  document.addEventListener('input', function (event) {
    if (event.target.dataset && event.target.dataset.counter) sync(event.target);
  });

  document.addEventListener('DOMContentLoaded', function () {
    document.querySelectorAll('[data-counter]').forEach(sync);
  });
})();


/*
 * ============================================================
 * PHONE — country-code prefix
 * ============================================================
 * Markup and layout are in the PHONE section of input.css. Opt in with
 * data-phone on the field:
 *
 *   <div class="input-field input-phone" data-phone>
 *     <button class="input-phone__prefix" type="button" aria-expanded="false"
 *             aria-controls="mobile-codes" aria-label="Dialling code">
 *       <span class="input-phone__code">+44</span>
 *       <span class="input-phone__chevron">…chevron…</span>
 *     </button>
 *     <input class="input" type="tel" …>
 *     <input type="hidden" data-phone-code value="+44">
 *     <div class="dropdown-list input-phone__list" id="mobile-codes" role="listbox" hidden>
 *       <button class="dropdown-item" type="button" role="option" data-code="+44">…</button>
 *     </div>
 *   </div>
 *
 * Only the prefix opens the list — clicking anywhere else in the field puts the
 * caret in the number, which is what the field is mostly for. Picking a country
 * writes its code into the panel and the hidden input, then returns focus to the
 * number so the flow carries on where it left off.
 * ============================================================
 */

(function () {
  function list(root)   { return root.querySelector('.input-phone__list'); }
  function number(root) { return root.querySelector('.input'); }

  function open(root, yes) {
    var menu = list(root);
    if (!menu) return;
    root.setAttribute('data-open', yes ? 'true' : 'false');
    menu.hidden = !yes;
    var prefix = root.querySelector('.input-phone__prefix');
    if (prefix) prefix.setAttribute('aria-expanded', yes ? 'true' : 'false');
  }

  function closeAll(except) {
    document.querySelectorAll('[data-phone][data-open="true"]').forEach(function (root) {
      if (root !== except) open(root, false);
    });
  }

  document.addEventListener('click', function (event) {
    var root = event.target.closest && event.target.closest('[data-phone]');
    if (!root) { closeAll(null); return; }
    closeAll(root);

    var picked = event.target.closest('.input-phone__list .dropdown-item');
    if (picked) {
      var code = picked.getAttribute('data-code') || '';
      var shown = root.querySelector('.input-phone__code');
      var store = root.querySelector('[data-phone-code]');
      if (shown) shown.textContent = code;
      if (store) store.value = code;

      root.querySelectorAll('.input-phone__list .dropdown-item').forEach(function (row) {
        row.setAttribute('aria-selected', String(row === picked));
      });

      open(root, false);
      var el = number(root);
      if (el) el.focus();
      return;
    }

    if (event.target.closest('.input-phone__prefix')) {
      open(root, root.getAttribute('data-open') !== 'true');
    }
  });

  document.addEventListener('keydown', function (event) {
    var root = event.target.closest && event.target.closest('[data-phone]');
    if (!root || event.key !== 'Escape') return;
    if (root.getAttribute('data-open') !== 'true') return;
    open(root, false);
    var prefix = root.querySelector('.input-phone__prefix');
    if (prefix) prefix.focus();
    event.preventDefault();
  });
})();


/*
 * ============================================================
 * EMAIL — data-validate="email"
 * ============================================================
 * A format check, not a required check: an empty field is left to whatever owns
 * "required" (in the prototype, the journey's Continue gate). Judged on blur and
 * cleared the moment the field is edited — the same "confirm live, complain
 * late" timing the rest of the journey uses, since complaining at someone
 * halfway through typing an address they haven't finished is noise.
 *
 * The test is deliberately loose: something before an @, something after it, and
 * a dot in the tail. Anything stricter starts rejecting addresses that work.
 * Copy comes from data-email-error.
 * ============================================================
 */

(function () {
  var LOOKS_LIKE_EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  var seq = 0;

  function group(el) { return el.closest('.input-group') || el.parentElement; }

  function show(el, text) {
    var host = group(el);
    var msg  = host.querySelector('.input-message--error');
    if (!msg) {
      msg = document.createElement('p');
      msg.className = 'input-message input-message--error';
      msg.id = 'input-email-message-' + (++seq);
      msg.setAttribute('role', 'alert');
      host.appendChild(msg);
    }
    msg.textContent = text;
    el.closest('.input-field').classList.add('input-field--error');
    el.setAttribute('aria-invalid', 'true');
    el.setAttribute('aria-describedby', msg.id);
  }

  function hide(el) {
    var msg = group(el).querySelector('.input-message--error');
    if (msg) msg.remove();
    el.closest('.input-field').classList.remove('input-field--error');
    el.removeAttribute('aria-invalid');
    el.removeAttribute('aria-describedby');
  }

  document.addEventListener('blur', function (event) {
    var el = event.target;
    if (!el.dataset || el.dataset.validate !== 'email') return;
    var value = el.value.trim();
    if (!value || LOOKS_LIKE_EMAIL.test(value)) hide(el);
    else show(el, el.dataset.emailError || 'Please provide a valid email address.');
  }, true);

  document.addEventListener('input', function (event) {
    var el = event.target;
    if (el.dataset && el.dataset.validate === 'email') hide(el);
  });
})();


/*
 * ============================================================
 * DATE ENTRY — segmented, DD / MM / YYYY or MM / YYYY
 * ============================================================
 * Inputs either side of real "/" elements, so the separators are on screen
 * before anything is typed and never move. Markup and the reasoning behind the
 * segment widths are in the DATE ENTRY section of input.css.
 *
 * The segments are whatever the markup declares, in DOM order — a purchase date
 * is month + year, a date of birth is day + month + year. Each part names itself
 * with a modifier class and the ranges below come from that, so adding a part is
 * a markup change rather than a code one.
 *
 * TYPING
 *   - digits only; each segment is capped by its own maxlength
 *   - a first digit that could only be a padded value is padded: "5" in a month
 *     becomes "05", "4" in a day becomes "04", and focus moves on. A second
 *     digit that would push the part out of range is refused. So a month outside
 *     01–12 or a day outside 01–31 can't be typed at all, which is why there is
 *     no message for either.
 *   - a full segment hands over to the next one
 *   - Backspace in an empty segment steps back into the previous one, and the
 *     arrow keys cross between segments at their edges
 *
 * FUTURE DATES — data-date-max="today"
 * Judged once every segment is full, since a part-typed year says nothing. A
 * date after today shows an error below the field and marks the segments
 * aria-invalid; editing any segment clears it, and it comes back if the date is
 * still in the future. The keystrokes aren't swallowed — refusing them silently
 * reads as a broken field, where a message says what is actually wrong. Copy
 * comes from data-date-error, so it stays with the page.
 *
 * A WINDOW — data-date-within="3"
 * Both bounds at once: no later than today and no earlier than N years back.
 * For a question that asks about a period — claims in the last 3 years,
 * convictions in the last 5 — where a date outside the window isn't being asked
 * about at all. Implies data-date-max="today", so it replaces it rather than
 * joining it, and shares data-date-error.
 *
 * Day ranges are 01–31 regardless of month: a real calendar check would need
 * copy for "that date doesn't exist", which no design specifies yet.
 * ============================================================
 */

(function () {
  var seq = 0;                                  /* for unique message ids */

  /* max value, and the first-digit threshold above which the only possible
     value is a zero-padded one */
  var RANGES = {
    day:   { max: 31, pad: 3 },
    month: { max: 12, pad: 1 },
    year:  { max: null }
  };

  function digits(str) { return (String(str).match(/\d/g) || []).join(''); }

  /* Segments in DOM order */
  function segments(root) {
    return Array.prototype.slice.call(root.querySelectorAll('.input-date__part'));
  }

  function kindOf(part) {
    for (var name in RANGES) {
      if (part.classList.contains('input-date__part--' + name)) return name;
    }
    return 'year';                              /* unlabelled: treat as free digits */
  }

  function full(part) {
    return digits(part.value).length === (+part.getAttribute('maxlength') || 0);
  }

  function caretToEnd(el) {
    try { el.setSelectionRange(el.value.length, el.value.length); } catch (e) {}
  }


  /* --- error message ---------------------------------------------------- */

  function show(root, text) {
    var group = root.closest('.input-group') || root.parentElement;
    var msg   = group.querySelector('.input-message--error');
    if (!msg) {
      msg = document.createElement('p');
      msg.className = 'input-message input-message--error';
      msg.id        = 'input-date-message-' + (++seq);
      msg.setAttribute('role', 'alert');
      group.appendChild(msg);
    }
    msg.textContent = text;

    root.classList.add('input-field--error');
    segments(root).forEach(function (el) {
      el.setAttribute('aria-invalid', 'true');
      el.setAttribute('aria-describedby', msg.id);
    });
  }

  function hide(root) {
    var group = root.closest('.input-group') || root.parentElement;
    var msg   = group.querySelector('.input-message--error');
    if (msg) msg.remove();

    root.classList.remove('input-field--error');
    segments(root).forEach(function (el) {
      el.removeAttribute('aria-invalid');
      el.removeAttribute('aria-describedby');
    });
  }


  /* --- validation ------------------------------------------------------- */

  function check(root) {
    var parts = segments(root);
    if (!parts.length || !parts.every(full)) { hide(root); return true; }

    var within = +root.dataset.dateWithin || 0;

    if (root.dataset.dateMax === 'today' || within) {
      var value = {};
      parts.forEach(function (p) { value[kindOf(p)] = +digits(p.value); });

      var now  = new Date();
      var year = value.year;
      /* Day is optional: a month/year date counts as in the past for the whole
         of that month, which is what a purchase date means. */
      var future = year > now.getFullYear()
        || (year === now.getFullYear() && value.month > now.getMonth() + 1)
        || (year === now.getFullYear() && value.month === now.getMonth() + 1
            && value.day !== undefined && value.day > now.getDate());

      /* The floor of the window, N years back to the same month. Compared the
         same way round as the ceiling above, so the two agree about a date that
         lands exactly on the boundary month: it is inside the window. */
      var floorYear = now.getFullYear() - within;
      var early = within && (year < floorYear
        || (year === floorYear && value.month < now.getMonth() + 1));

      if (future || early) {
        show(root, root.dataset.dateError || 'That date is in the future.');
        return false;
      }
    }

    hide(root);
    return true;
  }


  /* --- typing ----------------------------------------------------------- */

  function onType(root, part) {
    var parts = segments(root);
    var range = RANGES[kindOf(part)] || {};
    var typed = digits(part.value);
    var next  = parts[parts.indexOf(part) + 1];

    if (range.max) {
      if (typed.length === 1 && +typed > range.pad) {   /* can only be 0X */
        part.value = '0' + typed;
        if (next) next.focus();
        return;
      }
      if (full(part) && (+typed < 1 || +typed > range.max)) {
        part.value = typed.slice(0, -1);                /* refuse the last digit */
        return;
      }
    }

    part.value = typed;
    if (full(part) && next) next.focus();
  }

  document.addEventListener('input', function (event) {
    var el = event.target;
    if (!el.classList || !el.classList.contains('input-date__part')) return;

    var root = el.closest('.input-date');
    if (!root) return;

    onType(root, el);
    check(root);
  });

  document.addEventListener('keydown', function (event) {
    var el = event.target;
    if (!el.classList || !el.classList.contains('input-date__part')) return;

    var root = el.closest('.input-date');
    if (!root) return;
    var parts = segments(root);
    var at    = parts.indexOf(el);
    var prev  = parts[at - 1];
    var next  = parts[at + 1];

    /* Backspace in an empty segment steps back with the caret at the end, so
       the next press eats a digit rather than doing nothing */
    if (event.key === 'Backspace' && !el.value && prev) {
      prev.focus();
      caretToEnd(prev);
      return;
    }
    if (event.key === 'ArrowLeft' && prev && el.selectionStart === 0) {
      prev.focus();
      caretToEnd(prev);
      event.preventDefault();
    }
    if (event.key === 'ArrowRight' && next && el.selectionStart === el.value.length) {
      next.focus();
      try { next.setSelectionRange(0, 0); } catch (e) {}
      event.preventDefault();
    }
  });

  /* Judge anything pre-filled in the markup */
  document.addEventListener('DOMContentLoaded', function () {
    document.querySelectorAll('.input-date').forEach(check);
  });
})();


/* ==== components/modal/modal.js ==== */
/*
 * ============================================================
 * MODAL — open, close, and the things that should close it
 * ============================================================
 * Declarative:  <button data-modal-open="discard">   <button data-modal-close>
 * From script:  Modal.open('discard' | element)  ·  Modal.close(...)  ·  Modal.isOpen()
 *
 * Closing is deliberately generous — backdrop, Escape, and any [data-modal-close]
 * — because a dialogue you cannot dismiss is a trap. The exception is opt-out:
 * data-modal-locked keeps a modal up until one of its own actions is taken, for
 * the rare case where dismissing IS an answer and shouldn't be given by accident.
 *
 * Mounted on <body> when opened. A modal is fixed, and an ancestor carrying
 * container-type, contain or a transform becomes the containing block for fixed
 * descendants — inside a card it would be pinned to the card. Moving it is the
 * only reliable fix, so it happens here rather than being left to remember.
 *
 * Focus: the panel takes focus on open and the opener gets it back on close, so
 * keyboard and screen-reader users aren't dropped at the top of the page. Focus
 * is not trapped — that wants a full implementation, see KNOWN-ISSUES.
 * ============================================================
 */

(function () {
  var openers = [];        /* stack: what to hand focus back to, per open modal */

  function find(target) {
    if (!target) return null;
    return typeof target === 'string' ? document.getElementById(target) : target;
  }

  function open(target, opener) {
    var modal = find(target);
    if (!modal || !modal.hidden) return null;

    if (modal.parentElement !== document.body) document.body.appendChild(modal);
    modal.hidden = false;
    /* Stop the page behind from scrolling under the scrim */
    document.documentElement.style.overflow = 'hidden';

    openers.push(opener || document.activeElement);

    var panel = modal.querySelector('.modal__panel');
    if (panel) {
      if (!panel.hasAttribute('tabindex')) panel.setAttribute('tabindex', '-1');
      panel.focus();
    }
    return modal;
  }

  function close(target) {
    var modal = find(target) || document.querySelector('.modal:not([hidden])');
    if (!modal || modal.hidden) return;

    modal.hidden = true;
    if (!document.querySelector('.modal:not([hidden])')) {
      document.documentElement.style.overflow = '';
    }

    var opener = openers.pop();
    if (opener && opener.isConnected && typeof opener.focus === 'function') opener.focus();
  }

  function isOpen(target) {
    var modal = find(target);
    return modal ? !modal.hidden : !!document.querySelector('.modal:not([hidden])');
  }

  document.addEventListener('click', function (event) {
    var opener = event.target.closest('[data-modal-open]');
    if (opener) { open(opener.getAttribute('data-modal-open'), opener); return; }

    var closer = event.target.closest('[data-modal-close]');
    if (closer) { close(closer.closest('.modal')); return; }

    /* Backdrop — the scrim itself, not anything inside the panel */
    var modal = event.target.closest('.modal');
    if (modal && event.target === modal && !modal.hasAttribute('data-modal-locked')) close(modal);
  });

  document.addEventListener('keydown', function (event) {
    if (event.key !== 'Escape') return;
    var modal = document.querySelector('.modal:not([hidden])');
    if (modal && !modal.hasAttribute('data-modal-locked')) close(modal);
  });

  window.Modal = { open: open, close: close, isOpen: isOpen };
})();


/* ==== components/optional-input/optional-input.js ==== */
/*
 * ============================================================
 * OPTIONAL INPUT — dismissal checkbox behaviour
 * ============================================================
 * Ticking the checkbox marks the value as not applicable, so the field is
 * disabled (Figma "Box ticked = Yes"); unticking re-enables it.
 *
 * The typed value is left alone rather than cleared — unticking by accident
 * shouldn't destroy what someone entered. Read the checkbox when submitting to
 * decide whether the field counts.
 *
 * Self-initialising via event delegation, and it syncs any markup that starts
 * out checked — just include the script:
 *   <script src="optional-input.js" defer></script>
 * ============================================================
 */

(function () {
  function sync(box) {
    var root  = box.closest('.optional-input');
    if (!root) return;
    var field  = root.querySelector('.input-field');
    /* querySelectorAll, not querySelector — a segmented date field has an input
       per segment and every one of them has to go disabled */
    var inputs = root.querySelectorAll('.input');
    if (!field || !inputs.length) return;

    inputs.forEach(function (input) { input.disabled = box.checked; });
    field.classList.toggle('input-field--disabled', box.checked);
  }

  document.addEventListener('change', function (event) {
    var box = event.target;
    if (box && box.classList && box.classList.contains('checkbox__input')) sync(box);
  });

  document.addEventListener('DOMContentLoaded', function () {
    document.querySelectorAll('.optional-input .checkbox__input').forEach(sync);
  });
})();


/* ==== components/pagination/pagination.js ==== */
/*
 * Pagination Indicator — click to activate
 * Clicking a dot makes it the single active dot within its .pagination.
 * (Optional helper; the component is purely presentational without it.)
 */
(function () {
  'use strict';

  document.addEventListener('click', function (e) {
    var dot = e.target.closest('.pagination__dot');
    if (!dot) return;
    var group = dot.closest('.pagination');
    if (!group) return;
    group.querySelectorAll('.pagination__dot').forEach(function (d) {
      var active = d === dot;
      d.classList.toggle('pagination__dot--active', active);
      if (d.hasAttribute('aria-selected')) d.setAttribute('aria-selected', active ? 'true' : 'false');
    });
  });
})();


/* ==== components/sales-nav/sales-nav.js ==== */
/*
 * Sales Navigation — Help/Close toggle, and the sticky bar's scrolled state
 * Delegated click handler: pressing the toggle flips [data-expanded] on the
 * nearest .sales-nav, which shows/hides the Call-us dropdown and swaps the
 * pill between Help and Close (all styling handled in CSS).
 */
(function () {
  document.addEventListener('click', function (e) {
    var toggle = e.target.closest('.sales-nav__toggle');
    if (toggle) {
      var nav = toggle.closest('.sales-nav');
      if (!nav) return;
      var open = nav.getAttribute('data-expanded') === 'true';
      nav.setAttribute('data-expanded', open ? 'false' : 'true');
      toggle.setAttribute('aria-expanded', open ? 'false' : 'true');
      return;
    }
    // click outside an expanded nav closes it
    document.querySelectorAll('.sales-nav[data-expanded="true"]').forEach(function (nav) {
      if (!nav.contains(e.target)) {
        nav.setAttribute('data-expanded', 'false');
        var t = nav.querySelector('.sales-nav__toggle');
        if (t) t.setAttribute('aria-expanded', 'false');
      }
    });
  });
})();


/*
 * Sticky bar — the scrolled state
 * -----------------------------------------------------------------
 * Flags every .sales-nav--sticky with [data-scrolled] once the page has moved,
 * which is what reveals the hairline along its bottom edge (see sales-nav.css).
 * At rest the bar and the page share a background and want no seam; the line is
 * only true once there is content passing behind the bar.
 *
 * Read off the scrolling element rather than an IntersectionObserver sentinel:
 * the question is simply "has the page moved at all", and a sentinel would need
 * markup every consumer has to remember to add.
 *
 * The listener is passive and does nothing but toggle an attribute the browser
 * ignores when unchanged, so it stays cheap without throttling.
 */
(function () {
  function sync() {
    var scrolled = (window.scrollY || document.documentElement.scrollTop) > 0;
    document.querySelectorAll('.sales-nav--sticky').forEach(function (nav) {
      if (scrolled) nav.setAttribute('data-scrolled', '');
      else nav.removeAttribute('data-scrolled');
    });
  }

  window.addEventListener('scroll', sync, { passive: true });
  /* A page restored mid-scroll starts scrolled — don't wait for a first move */
  window.addEventListener('load', sync);
  document.addEventListener('DOMContentLoaded', sync);
})();


/* ==== components/segment/segment.js ==== */
/*
 * ============================================================
 * SEGMENT CONTROL — selection behaviour
 * ============================================================
 * Clicking a segment selects it and deselects the others in the same control
 * (updating aria-selected). Disabled segments are ignored.
 *
 * Self-initialising via event delegation — just include the script:
 *   <script src="segment.js"></script>
 * ============================================================
 */

(function () {
  document.addEventListener('click', function (event) {
    var item = event.target.closest('.segment__item');
    if (!item || item.disabled) return;

    var control = item.closest('.segment');
    if (!control) return;

    control.querySelectorAll('.segment__item').forEach(function (seg) {
      var selected = seg === item;
      seg.classList.toggle('segment__item--active', selected);
      seg.setAttribute('aria-selected', selected ? 'true' : 'false');
    });
  });
})();


/* ==== components/tab-bar/tab-bar.js ==== */
/*
 * ============================================================
 * TAB (tab bar) — selection behaviour
 * ============================================================
 * Clicking a tab in a role="tablist" bar makes it active and deactivates the
 * previously-active tab (updating aria-selected). Disabled tabs are ignored.
 *
 * Self-initialising via event delegation — just include the script:
 *   <script src="tab-bar.js"></script>
 *
 * Scoped to .tabs[role="tablist"] so static state demos (a plain .tabs
 * without the role) aren't made interactive.
 * ============================================================
 */

(function () {
  document.addEventListener('click', function (event) {
    var tab = event.target.closest('.tab-item');
    if (!tab || tab.disabled) return;

    var bar = tab.closest('.tabs[role="tablist"]');
    if (!bar) return;

    bar.querySelectorAll('.tab-item').forEach(function (t) {
      var isActive = t === tab;
      t.classList.toggle('tab-item--active', isActive);
      t.setAttribute('aria-selected', isActive ? 'true' : 'false');
    });
  });
})();


/* ==== components/tier-card/tier-card.js ==== */
/*
 * Tier Card — group selection
 * Cards sharing a [data-tier-group] behave as a single-select set: clicking a
 * card's .tier-card__select makes it the active card and clears the others.
 * The button shows its data-label when unselected. When selected it shows
 * data-selected-label if present, otherwise "{data-label} selected".
 */
(function () {
  'use strict';

  function labelFor(btn) {
    return btn.getAttribute('data-label') || btn.textContent.trim().replace(/\s+selected$/i, '');
  }

  function selectedLabelFor(btn) {
    return btn.getAttribute('data-selected-label') || labelFor(btn) + ' selected';
  }

  function setLabel(btn, active) {
    if (btn) btn.textContent = active ? selectedLabelFor(btn) : labelFor(btn);
  }

  function selectCard(card) {
    var group = card.getAttribute('data-tier-group');
    var scope = card.parentElement || document;

    if (group) {
      scope.querySelectorAll('.tier-card[data-tier-group="' + group + '"]').forEach(function (c) {
        var active = c === card;
        c.classList.toggle('tier-card--active', active);
        setLabel(c.querySelector('.tier-card__select'), active);
      });
    } else {
      card.classList.toggle('tier-card--active');
      setLabel(card.querySelector('.tier-card__select'), card.classList.contains('tier-card--active'));
    }
  }

  document.addEventListener('click', function (e) {
    var btn = e.target.closest('.tier-card__select');
    if (!btn) return;
    var card = btn.closest('.tier-card');
    if (card) selectCard(card);
  });
})();


/* ==== components/tier-section/tier-section.js ==== */
/*
 * Tier Section — billing period pricing
 * The prices in each Tier Card are stored as the MONTHLY amount on
 * `.tier-card__price[data-monthly]`. Clicking a billing Segment item that
 * carries data-period ("annual" | "monthly") reprices every tier in that
 * section: annual = monthly × 12.
 */
(function () {
  'use strict';

  function fmt(n) { return '£' + n.toFixed(2); }

  function reprice(section, period) {
    section.querySelectorAll('.tier-card__price[data-monthly]').forEach(function (el) {
      var monthly = parseFloat(el.getAttribute('data-monthly'));
      if (isNaN(monthly)) return;
      el.textContent = period === 'annual' ? fmt(monthly * 12) : fmt(monthly);
    });
  }

  document.addEventListener('click', function (e) {
    var item = e.target.closest('.tier-section .segment__item[data-period]');
    if (!item) return;
    var section = item.closest('.tier-section');
    if (section) reprice(section, item.getAttribute('data-period'));
  });


  /* --------------------------------------------------------
     Mobile carousel ↔ pagination
     On the horizontal tier scroller, keep the pagination dot in sync with the
     centred card, and let a dot click scroll its card to centre.
     -------------------------------------------------------- */

  function centredIndex(scroller, cards) {
    var box = scroller.getBoundingClientRect();
    var mid = box.left + box.width / 2;
    var best = 0, bestDist = Infinity;
    cards.forEach(function (c, i) {
      var r = c.getBoundingClientRect();
      var dist = Math.abs(r.left + r.width / 2 - mid);
      if (dist < bestDist) { bestDist = dist; best = i; }
    });
    return best;
  }

  function initCarousel(section) {
    var scroller = section.querySelector('.tier-section__tiers');
    var pager = section.querySelector('.tier-section__pagination');
    if (!scroller || !pager) return;
    var cards = Array.prototype.slice.call(scroller.querySelectorAll('.tier-card'));
    var dots = Array.prototype.slice.call(pager.querySelectorAll('.pagination__dot'));
    if (!cards.length || !dots.length) return;

    function sync() {
      var idx = centredIndex(scroller, cards);
      dots.forEach(function (d, i) {
        var on = i === idx;
        d.classList.toggle('pagination__dot--active', on);
        if (d.hasAttribute('aria-selected')) d.setAttribute('aria-selected', on ? 'true' : 'false');
      });
    }

    var ticking = false;
    scroller.addEventListener('scroll', function () {
      if (ticking) return;
      ticking = true;
      requestAnimationFrame(function () { ticking = false; sync(); });
    });

    dots.forEach(function (d, i) {
      d.addEventListener('click', function () {
        if (cards[i]) cards[i].scrollIntoView({ behavior: 'smooth', inline: 'center', block: 'nearest' });
      });
    });

    sync();
  }

  function initAll() {
    document.querySelectorAll('.tier-section').forEach(initCarousel);
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initAll);
  } else {
    initAll();
  }
})();


/* ==== components/top-nav/top-nav.js ==== */
/*
 * ============================================================
 * TOP NAVIGATION / PLATFORM — expand + copy
 * ============================================================
 * Pressing Help (desktop) or the menu button (mobile) toggles [data-expanded]
 * on the nearest .top-nav, opening the dropdown and swapping Help⇄Close /
 * menu⇄close. The copy button copies the quote reference to the clipboard.
 * Click-outside and Escape close the panel.
 *
 * Self-init via event delegation:  <script src="top-nav.js" defer></script>
 * ============================================================
 */
(function () {
  function closeAll(except) {
    document.querySelectorAll('.top-nav[data-expanded="true"]').forEach(function (nav) {
      if (nav === except) return;
      nav.setAttribute('data-expanded', 'false');
      nav.querySelectorAll('[aria-expanded]').forEach(function (t) { t.setAttribute('aria-expanded', 'false'); });
    });
  }

  document.addEventListener('click', function (event) {
    // Copy the quote reference
    var copyBtn = event.target.closest('.top-nav__copy-btn');
    if (copyBtn) {
      var value = copyBtn.closest('.top-nav__copy').querySelector('.top-nav__copy-value');
      var text = value ? value.textContent.trim() : '';
      if (navigator.clipboard && text) navigator.clipboard.writeText(text).catch(function () {});
      copyBtn.classList.add('is-copied');
      copyBtn.setAttribute('aria-label', 'Copied');
      setTimeout(function () { copyBtn.classList.remove('is-copied'); copyBtn.setAttribute('aria-label', 'Copy'); }, 1500);
      return;
    }

    // Toggle the dropdown (Help pill or mobile menu button)
    var toggle = event.target.closest('.top-nav__help, .top-nav__menu');
    if (toggle) {
      var nav = toggle.closest('.top-nav');
      if (!nav) return;
      var open = nav.getAttribute('data-expanded') === 'true';
      closeAll(nav);
      nav.setAttribute('data-expanded', open ? 'false' : 'true');
      nav.querySelectorAll('[aria-expanded]').forEach(function (t) { t.setAttribute('aria-expanded', open ? 'false' : 'true'); });
      return;
    }

    // Click outside an open nav closes it
    document.querySelectorAll('.top-nav[data-expanded="true"]').forEach(function (nav) {
      if (!nav.contains(event.target)) {
        nav.setAttribute('data-expanded', 'false');
        nav.querySelectorAll('[aria-expanded]').forEach(function (t) { t.setAttribute('aria-expanded', 'false'); });
      }
    });
  });

  document.addEventListener('keydown', function (event) {
    if (event.key === 'Escape') closeAll(null);
  });
})();


/* ==== components/trustpilot-reviews/trustpilot-reviews.js ==== */
/*
 * Trustpilot Reviews — carousel controls
 * Desktop prev/next arrows scroll the review track by a page; on mobile the
 * pagination dot follows the centred card and a dot click scrolls to it.
 */
(function () {
  'use strict';

  function centredIndex(track, cards) {
    var box = track.getBoundingClientRect();
    var mid = box.left + box.width / 2;
    var best = 0, bestDist = Infinity;
    cards.forEach(function (c, i) {
      var r = c.getBoundingClientRect();
      var dist = Math.abs(r.left + r.width / 2 - mid);
      if (dist < bestDist) { bestDist = dist; best = i; }
    });
    return best;
  }

  function init(widget) {
    var track = widget.querySelector('.tp-reviews__track');
    if (!track) return;
    var cards = Array.prototype.slice.call(track.querySelectorAll('.tp-review'));
    var dots = Array.prototype.slice.call(widget.querySelectorAll('.tp-reviews__pagination .pagination__dot'));

    function syncDots() {
      if (!dots.length) return;
      var idx = centredIndex(track, cards);
      dots.forEach(function (d, i) {
        var on = i === idx;
        d.classList.toggle('pagination__dot--active', on);
        if (d.hasAttribute('aria-selected')) d.setAttribute('aria-selected', on ? 'true' : 'false');
      });
    }

    var ticking = false;
    track.addEventListener('scroll', function () {
      if (ticking) return;
      ticking = true;
      requestAnimationFrame(function () { ticking = false; syncDots(); });
    });

    widget.querySelectorAll('.tp-reviews__nav').forEach(function (btn) {
      btn.addEventListener('click', function () {
        var dir = btn.getAttribute('data-dir') === 'prev' ? -1 : 1;
        track.scrollBy({ left: dir * Math.round(track.clientWidth * 0.9), behavior: 'smooth' });
      });
    });

    dots.forEach(function (d, i) {
      d.addEventListener('click', function () {
        if (cards[i]) cards[i].scrollIntoView({ behavior: 'smooth', inline: 'center', block: 'nearest' });
      });
    });

    syncDots();
  }

  function initAll() { document.querySelectorAll('.tp-reviews').forEach(init); }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initAll);
  } else {
    initAll();
  }
})();


/* ==== components/vehicle-registration/vehicle-registration.js ==== */
/*
 * ============================================================
 * VEHICLE REGISTRATION — length validation
 * ============================================================
 * Opt in per instance by putting data-veh-reg on the wrapper:
 *
 *   <div class="veh-reg" data-veh-reg
 *        data-length="7"
 *        data-error-required="Vehicle registration is required."
 *        data-error-invalid="We couldn't find your vehicle…">
 *     <div class="veh-reg__field">
 *       …country badge…
 *       <input class="veh-reg__input" type="text" aria-label="Registration">
 *       <span class="veh-reg__status" role="img" aria-label="Registration complete">
 *         <svg viewBox="0 0 24 24" fill="none">
 *           <path class="veh-reg__status-disc"  d="…"/>
 *           <path class="veh-reg__status-glyph" d="…"/>
 *         </svg>
 *       </span>
 *     </div>
 *   </div>
 *
 * RULES
 *   - Length counts letters and digits only, so the space in "SH48 HSA" is
 *     free and "SH48HSA" and "sh48 hsa" all count as 7.
 *   - Hitting exactly data-length (default 7 — the UK plate format) marks the
 *     field valid and reveals the trailing tick. This is live, per keystroke.
 *   - A wrong length only surfaces an error once the field is left, or a gated
 *     control is pressed. Validating live would put "check the registration"
 *     on screen from the first letter typed. Editing clears the error again.
 *   - Empty and submitted → data-error-required.
 *     Wrong length, on blur or submit → data-error-invalid.
 *   - Typing is upper-cased in the value, not just by text-transform, so what
 *     is read back off the field matches what's on the plate.
 *
 * GATING A CONTROL
 *   <button data-veh-reg-submit>Find vehicle</button>
 * While the field is invalid the click is cancelled in the capture phase, so
 * handlers bound to the button itself — page navigation, form submit — never
 * run. Give the attribute a selector (data-veh-reg-submit="#reg") to name the
 * field; without one the nearest [data-veh-reg] is used.
 *
 * The error row is built here rather than sitting in the markup, since the copy
 * changes with the failure. It uses the component's own .veh-reg__message and
 * .veh-reg--error, so it looks the same as an error authored by hand.
 *
 * Self-initialising via event delegation — just include the script:
 *   <script src="vehicle-registration.js" defer></script>
 * ============================================================
 */

(function () {
  var DEFAULT_LENGTH = 7;                     /* 2 letters + 2 digits + 3 letters */

  /* icons/warning.svg — the circled "!" Figma shows on the Error state */
  var WARNING = '<svg viewBox="0 0 24 24" fill="none" aria-hidden="true">'
    + '<path d="M11 12.5C11 12.7761 11.2239 13 11.5 13H12.5C12.7761 13 13 12.7761 13 12.5L13 7.5C13 7.22386 12.7761 7 12.5 7L11.5 7C11.2239 7 11 7.22386 11 7.5L11 12.5Z" fill="currentColor"/>'
    + '<path d="M12 17C12.6904 17 13.25 16.4404 13.25 15.75C13.25 15.0596 12.6904 14.5 12 14.5C11.3096 14.5 10.75 15.0596 10.75 15.75C10.75 16.4404 11.3096 17 12 17Z" fill="currentColor"/>'
    + '<path fill-rule="evenodd" clip-rule="evenodd" d="M12 1C5.92487 1 1 5.92487 1 12C1 18.0751 5.92487 23 12 23C18.0751 23 23 18.0751 23 12C23 5.92487 18.0751 1 12 1ZM3 12C3 7.02944 7.02944 3 12 3C16.9706 3 21 7.02944 21 12C21 16.9706 16.9706 21 12 21C7.02944 21 3 16.9706 3 12Z" fill="currentColor"/>'
    + '</svg>';

  var seq = 0;                                /* for unique aria-describedby ids */

  function chars(value) { return (String(value).match(/[a-z0-9]/gi) || []).join(''); }

  function field(reg)  { return reg.querySelector('.veh-reg__field'); }
  function input(reg)  { return reg.querySelector('.veh-reg__input'); }
  function target(reg) { return parseInt(reg.dataset.length, 10) || DEFAULT_LENGTH; }

  function complete(reg) {
    var el = input(reg);
    return !!el && chars(el.value).length === target(reg);
  }


  /* --- error row ------------------------------------------------------- */

  function show(reg, text) {
    var row = reg.querySelector('.veh-reg__message');
    if (!row) {
      row = document.createElement('div');
      row.className = 'veh-reg__message';
      row.id        = 'veh-reg-message-' + (++seq);
      row.setAttribute('role', 'alert');      /* announce it when it appears */
      row.innerHTML = '<span class="veh-reg__message-icon">' + WARNING + '</span>'
                    + '<p class="veh-reg__message-text"></p>';
      reg.appendChild(row);
    }
    row.querySelector('.veh-reg__message-text').textContent = text;

    reg.classList.add('veh-reg--error');
    field(reg).classList.add('veh-reg__field--error');
    field(reg).classList.remove('veh-reg__field--valid');
    input(reg).setAttribute('aria-invalid', 'true');
    input(reg).setAttribute('aria-describedby', row.id);
  }

  function hide(reg) {
    var row = reg.querySelector('.veh-reg__message');
    if (row) row.remove();

    reg.classList.remove('veh-reg--error');
    field(reg).classList.remove('veh-reg__field--error');
    input(reg).removeAttribute('aria-invalid');
    input(reg).removeAttribute('aria-describedby');
  }


  /* --- state ----------------------------------------------------------- */

  /* Live pass: upper-case the value, flip the tick, and drop any standing
     error as soon as the field is touched. */
  function refresh(reg) {
    var el = input(reg);
    if (!el) return;

    var upper = el.value.toUpperCase();
    if (upper !== el.value) {
      var at = el.selectionStart;             /* same length, so the caret holds */
      el.value = upper;
      try { el.setSelectionRange(at, at); } catch (e) { /* not a text field */ }
    }

    field(reg).classList.toggle('veh-reg__field--valid', complete(reg));
    if (reg.classList.contains('veh-reg--error')) hide(reg);
  }

  /* Returns whether the field passes. `submitting` distinguishes leaving an
     empty field (say nothing — it hasn't been filled in yet) from trying to
     continue without one (say it's required). */
  function validate(reg, submitting) {
    if (complete(reg)) { hide(reg); return true; }

    var empty = chars(input(reg).value).length === 0;
    if (empty && !submitting) { hide(reg); return false; }

    show(reg, empty
      ? (reg.dataset.errorRequired || 'Vehicle registration is required.')
      : (reg.dataset.errorInvalid  || 'Check the registration number and try again.'));
    return false;
  }

  /* The [data-veh-reg] a gated control belongs to: the first one found in an
     ancestor, walking outwards, so a page with two fields gates the right one. */
  function fieldFor(control) {
    var selector = control.getAttribute('data-veh-reg-submit');
    if (selector) return document.querySelector(selector);

    for (var node = control.parentElement; node; node = node.parentElement) {
      var found = node.querySelector('[data-veh-reg]');
      if (found) return found;
    }
    return null;
  }


  /* --- wiring ---------------------------------------------------------- */

  document.addEventListener('input', function (event) {
    var el = event.target;
    if (!el.classList || !el.classList.contains('veh-reg__input')) return;
    var reg = el.closest('[data-veh-reg]');
    if (reg) refresh(reg);
  });

  /* blur doesn't bubble, so listen in the capture phase */
  document.addEventListener('blur', function (event) {
    var el = event.target;
    if (!el.classList || !el.classList.contains('veh-reg__input')) return;
    var reg = el.closest('[data-veh-reg]');
    if (reg) validate(reg, false);
  }, true);

  /* Capture, so this runs before any click handler on the control itself */
  document.addEventListener('click', function (event) {
    var control = event.target.closest && event.target.closest('[data-veh-reg-submit]');
    if (!control) return;

    var reg = fieldFor(control);
    if (!reg || validate(reg, true)) return;

    event.preventDefault();
    event.stopPropagation();
    input(reg).focus();
  }, true);

  /* Anything pre-filled in the markup starts in the right state */
  document.addEventListener('DOMContentLoaded', function () {
    document.querySelectorAll('[data-veh-reg]').forEach(refresh);
  });
})();
